<?php
namespace App\Http\Controllers\Auth;
use App\Http\Controllers\Controller; use App\Models\User; use App\Services\FileCompressionService; use Illuminate\Http\Request; use Illuminate\Support\Facades\Auth; use Illuminate\Support\Facades\Hash; use Illuminate\Validation\Rule;
class PortalAuthController extends Controller {
 public function login(Request $r){$v=$r->validate(['email'=>['required','email'],'password'=>['required','string'],'role'=>['required',Rule::in(['student','faculty'])]]);if(!Auth::attempt(['email'=>$v['email'],'password'=>$v['password'],'role'=>$v['role'],'is_active'=>true],$r->boolean('remember')))return response()->json(['message'=>'Invalid credentials or role.'],422);$r->session()->regenerate();$r->user()->forceFill(['last_login_at'=>now()])->save();return response()->json(['message'=>'Signed in successfully.']);}
 public function register(Request $r,FileCompressionService $images){$role=$r->input('role');$rules=['role'=>['required',Rule::in(['student','faculty'])],'name'=>'required|string|max:120','surname'=>'required|string|max:120','gender'=>'required|in:Male,Female,Other','college_name'=>'required|string|max:180','email'=>'required|email|max:190|unique:users,email','mobile'=>'nullable|digits:10|unique:users,mobile','password'=>'required|string|min:8|confirmed','address'=>'required|string|max:1000','pin_code'=>'nullable|digits:6','profile_photo'=>'nullable|image|max:5120'];if($role==='student')$rules+=['college_year'=>'required|string|max:30','branch'=>'required|in:CS,ME,EE,ET','semester'=>'required|in:I,II,III,IV,V,VI'];else $rules+=['subject_department'=>'required|string|max:255','employee_id'=>'nullable|string|max:100'];$v=$r->validate($rules);$photo=null;if($r->hasFile('profile_photo')){$photo=$r->file('profile_photo')->store('profiles','public');$images->compressImageInPlace(storage_path('app/public/'.$photo));}$user=User::create(array_merge($v,['profile_photo_path'=>$photo,'is_active'=>true]));Auth::login($user);$r->session()->regenerate();return response()->json(['message'=>'Account created successfully.']);}
 public function logout(Request $r){Auth::logout();$r->session()->invalidate();$r->session()->regenerateToken();return redirect('/');}
}
